#!/usr/bin/env python3
"""Exact builtin kernel axiom inventory; not a complete source or full gate."""
import json
from pathlib import Path
import re
import sys
PINS = {'Solidity.Backend.InternalFlow.CallArgumentPrefix.scalar_tail': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.storage_tail': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.memory_tail': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.call_failure': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.evaluated_prefix': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_arguments': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.good_arguments': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.body_executes': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.successful_call': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_call': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.successful_observations': ['propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_not_success': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_not_panic': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.wrong_scalar_order': ['propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.wrong_result_alias': ['propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_memory_suffix': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.wrong_private_escape': ['propext']}
NAMES = ['Solidity.Backend.InternalFlow.CallArgumentPrefix.scalar_tail', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.storage_tail', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.memory_tail', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.call_failure', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.evaluated_prefix', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_arguments', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.good_arguments', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.body_executes', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.successful_call', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_call', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.successful_observations', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_not_success', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_not_panic', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.wrong_scalar_order', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.wrong_result_alias', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.failed_memory_suffix', 'Solidity.Backend.InternalFlow.CallArgumentPrefix.Checks.wrong_private_escape']
def check(text):
    if re.search(r"(?:^|\n).*?(?:error:|error\(|sorryAx)",text):
        raise ValueError("Lean diagnostic or untrusted axiom")
    rows = [(n,sorted(x.strip()for x in a.split(',')if x.strip()))
        for n,a in re.findall(r"'([^']+)' (?:depends on axioms:\s*\[([^\]]*)\]|does not depend on any axioms)",text)]
    if rows != [(n,PINS[n])for n in NAMES]:
        raise ValueError("missing, extra, duplicate, reordered or changed axiom report")
    return len(rows)
log = Path(sys.argv[1]).read_text()
print(json.dumps({'status':'pass','reports':check(log)}))
